reearth.extension.on("message", function(msg) {
  // ── camera-test.js ──
  var action = msg.action;
  if (action === "set-tokyo") {
    reearth.camera.setView({
      lat: 35.681,
      lng: 139.767,
      height: 10000,
      heading: 0,
      pitch: -Math.PI / 2,
      roll: 0
    });
  } else if (action === "fly-sydney") {
    reearth.camera.flyTo(
      {
        lat: -33.87,
        lng: 151.21,
        height: 20000,
        heading: 0,
        pitch: -Math.PI / 2
      },
      { duration: 1 }
    );
  } else if (action === "zoom-in") {
    reearth.camera.zoomIn(2);
  }

  // ── engine-test.js ──
  var action = msg.action;
  if (action === "engine-info") {
    reearth.ui.postMessage({
      action: "engine-info-result",
      name: reearth.engine.name,
      apiVersion: reearth.apiVersion
    });
  }

  // ── modal-test.js ──
  var action = msg.action;
  if (action === "modal-show") {
    reearth.modal.on("close", function() {
      reearth.ui.postMessage({ action: "modal-closed" });
    }, { once: true });
    reearth.modal.show(
      '<button id="modal-inner">Modal Inner</button>' +
      '<output id="modal-received"></output>' +
      '<script>window.addEventListener("message", function(e) {' +
      'document.getElementById("modal-received").textContent = JSON.stringify(e.data);' +
      '});</script>',
      { width: 300, height: 200, background: "rgba(0,0,0,0.5)", clickBgToClose: true }
    );
  } else if (action === "modal-post") {
    reearth.modal.postMessage({ text: "hello modal" });
  } else if (action === "modal-update") {
    reearth.modal.update({ width: 500, height: 200, background: "rgba(0,0,0,0.5)", clickBgToClose: true });
  } else if (action === "modal-close") {
    reearth.modal.close();
  }

  // ── timeline-test.js ──
  var action = msg.action;
  if (action === "timeline-set-speed") {
    reearth.timeline.setSpeed(10);
  } else if (action === "timeline-set-step-fixed") {
    reearth.timeline.setStepType("fixed");
  } else if (action === "timeline-set-range-bounced") {
    reearth.timeline.setRangeType("bounced");
  } else if (action === "timeline-set-time") {
    reearth.timeline.setTime({
      start: "2024-01-01T00:00:00Z",
      stop: "2024-01-02T00:00:00Z",
      current: "2024-01-01T06:00:00Z"
    });
  } else if (action === "timeline-play") {
    reearth.timeline.play();
  } else if (action === "timeline-pause") {
    reearth.timeline.pause();
  }

  // ── viewer-test.js ──
  var action = msg.action;
  if (action === "viewer-mode-move") {
    reearth.viewer.interactionMode.override("move");
  } else if (action === "viewer-mode-default") {
    reearth.viewer.interactionMode.override("default");
  }
});
